//! Derives the subset of the Handy v3 protobuf code that the protocol sends.
//!
//! `hdy_rpc.rs` is generated by prost-build from the vendor's full schema, where `RpcMessage` is
//! a union of every request, response and notification the device knows. Using it directly drags
//! an encoder, decoder and `Debug` impl for all of them into the binary (~140 KB on a 32-bit
//! target), although the protocol only ever builds a handful of requests.
//!
//! This script copies the definitions the protocol needs verbatim and drops the other oneof
//! variants, so field tags and encodings are unchanged. Protobuf decoders skip unknown fields, so
//! decoding a device reply with the trimmed types still works; it just yields no payload.
//!
//! To use another request in the protocol, add its name to `REQUESTS`.

use std::{env, fmt::Write, fs, path::Path};

const SOURCE: &str = "src/device/protocol_impl/thehandy_v3/hdy_rpc.rs";

/// The `request::Params` variants (and their message structs) the protocol constructs.
const REQUESTS: &[&str] = &[
  "RequestBatteryGet",
  "RequestCapabilitiesGet",
  "RequestHdspXpTSet",
  "RequestHvpSet",
  "RequestHvpStop",
];

fn main() {
  println!("cargo:rerun-if-changed=build.rs");
  println!("cargo:rerun-if-changed={SOURCE}");

  let source = fs::read_to_string(SOURCE).expect("generated Handy v3 protobuf code is readable");
  let mut out = String::from("// Trimmed from hdy_rpc.rs by build.rs. Do not edit.\n");

  for request in REQUESTS {
    out.push_str(item(&source, &format!("pub struct {request} "), SOURCE));
  }

  let (params, tags) = keep_variants(item(&source, "pub mod request ", SOURCE), REQUESTS);
  out.push_str(&with_tags(item(&source, "pub struct Request ", SOURCE), "request::Params", &tags));
  out.push_str(&params);

  let (message, tags) = keep_variants(item(&source, "pub mod rpc_message ", SOURCE), &["Request"]);
  out.push_str(&with_tags(
    item(&source, "pub struct RpcMessage ", SOURCE),
    "rpc_message::Message",
    &tags,
  ));
  out.push_str(&message);

  out.push_str(item(&source, "pub enum MessageType ", SOURCE));

  let out_dir = env::var("OUT_DIR").expect("cargo sets OUT_DIR");
  fs::write(Path::new(&out_dir).join("thehandy_v3_rpc.rs"), out)
    .expect("trimmed Handy v3 protobuf code is writable");
}

/// The top-level item whose declaration line starts with `header`, including the attributes and
/// doc comments directly above it and a trailing newline.
fn item<'a>(source: &'a str, header: &str, file: &str) -> &'a str {
  let declaration = source
    .match_indices(header)
    .map(|(index, _)| index)
    .find(|&index| index == 0 || source.as_bytes()[index - 1] == b'\n')
    .unwrap_or_else(|| panic!("`{header}` not found in {file}"));

  let mut start = declaration;
  while let Some(previous) = source[..start].strip_suffix('\n') {
    let line_start = previous.rfind('\n').map_or(0, |index| index + 1);
    let line = &previous[line_start..];
    if !(line.starts_with("#[") || line.starts_with("///")) {
      break;
    }
    start = line_start;
  }

  let mut depth = 0usize;
  for (offset, byte) in source[declaration..].bytes().enumerate() {
    match byte {
      b'{' => depth += 1,
      b'}' => {
        depth -= 1;
        if depth == 0 {
          let end = declaration + offset + 1;
          let end = end + usize::from(source[end..].starts_with('\n'));
          return &source[start..end];
        }
      }
      _ => {}
    }
  }
  panic!("`{header}` in {file} has no closing brace");
}

/// Returns the oneof module with only the variants named in `keep`, and their tags as they go in
/// the `tags = "..."` attribute of the field holding the oneof.
fn keep_variants(module: &str, keep: &[&str]) -> (String, String) {
  let mut out = String::new();
  let mut tags = Vec::new();
  let mut found = Vec::new();
  // Doc comments and attributes of the variant that has not been seen yet.
  let mut pending = String::new();
  let mut in_enum = false;

  for line in module.lines() {
    let trimmed = line.trim();
    if !in_enum {
      in_enum = trimmed.starts_with("pub enum ");
      writeln!(out, "{line}").unwrap();
    } else if trimmed.starts_with("///") || trimmed.starts_with("#[") {
      writeln!(pending, "{line}").unwrap();
    } else if let Some((name, _)) = trimmed.split_once("(super::") {
      if keep.contains(&name) {
        let tag = pending
          .split_once("tag = \"")
          .and_then(|(_, rest)| rest.split_once('"'))
          .map(|(tag, _)| tag)
          .unwrap_or_else(|| panic!("variant `{name}` in {SOURCE} has no tag"));
        tags.push(tag.to_owned());
        found.push(name);
        out.push_str(&pending);
        writeln!(out, "{line}").unwrap();
      }
      pending.clear();
    } else {
      in_enum = trimmed != "}";
      writeln!(out, "{line}").unwrap();
    }
  }

  for name in keep {
    assert!(found.contains(name), "variant `{name}` not found in {SOURCE}");
  }
  (out, tags.join(", "))
}

/// Returns the message struct with the tag list of its `oneof` field replaced by `tags`.
fn with_tags(message: &str, oneof: &str, tags: &str) -> String {
  let marker = format!("oneof = \"{oneof}\"");
  let after_oneof = message
    .find(&marker)
    .unwrap_or_else(|| panic!("`{marker}` not found in {SOURCE}"))
    + marker.len();
  let tags_start = after_oneof
    + message[after_oneof..]
      .find("tags = \"")
      .unwrap_or_else(|| panic!("`{marker}` in {SOURCE} has no tags"))
    + "tags = \"".len();
  let tags_end = tags_start
    + message[tags_start..]
      .find('"')
      .unwrap_or_else(|| panic!("`{marker}` in {SOURCE} has an unterminated tag list"));
  format!("{}{tags}{}", &message[..tags_start], &message[tags_end..])
}
